do $rpg_invitation_test_environment$
begin
  if current_setting('server_version_num')::integer / 10000 <> 17 then
    raise exception 'RPG invitation runtime tests require PostgreSQL 17';
  end if;
  if to_regclass('auth.users') is null or to_regclass('realtime.messages') is null then
    raise exception 'Supabase Auth and Realtime objects are required';
  end if;
end
$rpg_invitation_test_environment$;

create table public.players (
  id bigint generated by default as identity primary key,
  user_id uuid not null unique,
  username text not null unique
);

create table public.realtime_room_access (
  topic text primary key,
  room_kind text not null check (room_kind in ('rpg', 'chess')),
  host_user_id uuid not null,
  invitee_user_id uuid,
  guest_user_id uuid,
  is_public boolean not null default false,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default (now() + interval '2 hours')
);

revoke all on public.players, public.realtime_room_access from public, anon, authenticated, service_role;

create extension if not exists pgtap with schema extensions;
